// --- Псалтирь: два псалма со сдвигом -----------------------------------------
//
// Псалтирь у обоих изданий по счёту Семидесяти, и сходится она почти вся: из
// 151 псалма длины расходятся у двенадцати, и в десяти из них НУМЕРАЦИЯ НЕ
// СЪЕЗЖАЕТ — греческий просто не печатает стиха (Пс. 63:3) или печатает лишний
// (Пс. 71:20). Правил таким не нужно.
//
// Сдвиг настоящий только в двух, и там он от разной разбивки: греческий держит
// в одном стихе то, что славянский разнёс на два.
const PSALM_SHIFTS: Array<[number, number, number, number, string]> = [
    [92, 5, 5, 1,
     "греч. Пс. 92:5 «τὰ μαρτύριά σου ἐπιστώθησαν σφόδρα» = слав. 92:6 «Свидѣ̑нїѧ твоѧ̑ ᲂу҆вѣ́ришасѧ ѕѣлѡ̀»; " +
     "слав. 92:5 о высотах морских греческий держит внутри своего 92:4"],
    [127, 4, 6, 1,
     "греч. Пс. 127:4 «ἰδοὺ οὕτως εὐλογηθήσεται ὁ ἄνθρωπος» = слав. 127:5 «Сѐ, та́кѡ бл҃гослови́тсѧ человѣ́къ»; " +
     "слав. 127:4 о сынах как масличных отраслях греческий держит внутри своего 127:3"],
];

const psalmRules: BibleMappingRule[] = PSALM_SHIFTS.map(
    ([chapter, verseFrom, verseTo, verseOffset, note]) => ({
        edition: "grc-lxx-pat",
        from: { book: "psaltir", chapter, verseFrom, verseTo },
        to: { verseOffset },
        exact: true,
        note,
    }),
);

// --- Остальные книги: разрозненные сдвиги ------------------------------------
//
// То, что осталось после Иеремии, Притчей, 3 Царств и Псалтири. Случаи разные,
// но приёма всего три, и они повторяются по всей Библии:
//
//   * ГЛАВА НАЧИНАЕТСЯ РАНЬШЕ. У греческого есть стих, которого славянский не
//     печатает (заглавие Песни Песней, «Ἰερειχὼ συνκεκλεισμένη» у Иисуса
//     Навина), и дальше вся глава идёт на стих вперёд.
//   * ГРАНИЦА ГЛАВ ПРОВЕДЕНА ИНАЧЕ. Греческий Левит держит в шестой главе то,
//     что славянский начинает седьмой.
//   * КУСОК СТОИТ В ДРУГОЙ ГЛАВЕ. Жертвенник на Гевале у греков в девятой
//     главе Иисуса Навина, у славян в конце восьмой.
//
// БЕЗДОМНЫЕ СТИХИ. Где у греческого стих есть, а у славянского места для него
// нет, стих уводится ЗА КОНЕЦ главы. Это не выдумка адреса, а уже принятый в
// разделе способ показывать излишек: такой стих становится отдельной строкой в
// конце с пустой славянской ячейкой — ровно так же, как показываются греческие
// стихи, до которых славянская глава просто не достаёт. Оставить его на месте
// нельзя: он столкнулся бы с чужим, а столкновение прячет один из двух молча.
