// --- Сфънта Скриптура: прочие книги -----------------------------------------
//
// Сорок семь глав, прочитанных построчно. Причины у них четыре, и они разные:
//
//   1. ПЕРЕНОС ЧЕРЕЗ ГРАНИЦУ ГЛАВЫ. Славянская и румынская режут книгу в
//      разных местах: слав. Нав. 5:16 об Иерихоне румынская начинает 6-й
//      главой, слав. Дан. 5:31 о Дарии Мидянине — 6-й, слав. Зах. 1:18–21 о
//      четырёх рогах — 2-й, а славословие слав. Рим. 14:24–26 румынская
//      печатает концом 16-й. Такие правила уводят стих в СОСЕДНЮЮ главу
//      (шестое поле — глава-цель), и без них стих просто пропал бы.
//
//   2. ДРОБЛЕНИЕ И СЛИЯНИЕ ВНУТРИ ГЛАВЫ — то же, что в Псалтири и Сирахе.
//
//   3. ИЗЪЯН НАБОРА. Ро Лев. 15 не имеет стиха 4 вовсе (счёт идёт 1,2,3,5…),
//      ро Дан. 6:1–4 разорваны надвое там, где потерялись числа «шестьдесят
//      два» и «сто двадцать», ро 1 Мак. 9:27 состоит из одного слова «Шѝ», а
//      ро Мк. 3:1 — это не стих, а заголовок отдела. Такие обрывки уводим за
//      конец главы: они покажутся лишней строкой, а не сядут на чужой адрес.
//
//   4. ПОТЕРЯННЫЙ НОМЕР — то же, что в Лев. 15, но отчёт этого НЕ ВИДИТ.
//      Пропал не текст, а число: счёт перескакивает (3 Цар. 2 идёт …44, 46, 47;
//      Дан. 11 — …20, 22…; Ис. 61 — …10, 12; Гал. 4 — …29, 31), стихов при этом
//      ровно столько же, сколько у славянской, и длины сходятся. Сверка по
//      длинам такую главу пропускает, а весь хвост её съехал на единицу.
//      Найдены проверкой ГРАНИЦ, а не длин: у каждой главы смотрим, встал ли
//      её первый стих на первый славянский, а последний — на последний. Где
//      не встал, там граница уехала, даже если длины сошлись.
//
//   5. РАЗНАЯ ВЁРСТКА СПИСКОВ — см. приговоры unmappable внизу файла.
