const matches = (rule: BibleMappingRule, book: string, chapter: number, verse: number): boolean => {
    if (rule.from.book !== book) return false;
    if (rule.from.chapter !== undefined && rule.from.chapter !== chapter) return false;
    if (rule.from.verseFrom !== undefined && verse < rule.from.verseFrom) return false;
    if (rule.from.verseTo !== undefined && verse > rule.from.verseTo) return false;
    return true;
};

/** Правила одного издания — их немного, поэтому просто фильтр без индекса. */
export const mappingsFor = (editionCode: string): BibleMappingRule[] =>
    BIBLE_MAPPINGS.filter((rule) => rule.edition === editionCode);

/**
 * Родная ссылка издания — в каноническую. Без подходящего правила возвращает
 * ту же ссылку: у большинства книг нумерация и есть каноническая.
 *
 * Правила передаются готовым списком, а не берутся по коду издания, чтобы
 * миграция не перебирала их заново на каждом из 73 тысяч стихов.
 */
export const toCanonRef = (
    rules: BibleMappingRule[],
    book: string,
    chapter: number,
    verse: number,
): CanonRef => {
    const rule = rules.find((candidate) => matches(candidate, book, chapter, verse));
    if (!rule) return { canonId: book, chapter, verse };

    return {
        canonId: rule.to.book ?? book,
        chapter: rule.to.chapter ?? chapter,
        verse: verse + (rule.to.verseOffset ?? 0),
    };
};


/**
 * Приговоры по главам, где длины изданий расходятся, а правила нет.
 *
 * Заведено, чтобы отличать три вещи, которые в отчёте выглядят одинаково —
 * пустой клеткой:
 *
 *   aligned     — СВЕРЕНО, сдвига нет. Издание просто не печатает части стихов,
 *                 но нумерация не съезжает, и правило только испортило бы верное
 *                 соответствие. Таких глав много, и каждая проверена по тексту.
 *   unmappable  — сверено, и правилом НЕ ВЫРАЗИТЬ. Правило выражает смещение;
 *                 оно бессильно там, где издания разбили текст по-разному: один
 *                 греческий стих отвечает двум славянским, и любое смещение
 *                 сталкивает два стиха на одном месте.
 *
 * Чего здесь нет — то и есть работа: глава, у которой длины разошлись, правила
 * не заведено и приговора не вынесено, значит до неё не дошли руки.
 */
export interface ChapterVerdict {
    edition: string;
    book: string;
    /** Пусто — приговор всей книге. */
    chapters?: number[];
    verdict: "aligned" | "unmappable";
    reason: string;
}

// Причина у просеянных глав одна на всех, и она честно слабее, чем у тех, что
// прочитаны построчно: длины стихов у перевода и подлинника связаны, и если
// «стих под своим номером» объясняет длины лучше любого сдвига, сдвига там нет.
// Это довод, а не доказательство; главу из этого списка стоит перечитать, если
// с ней что-то не сойдётся.
// Главы, прочитанные ПОСТРОЧНО по обеим книгам: у каждой найдена та граница,
// на которой счёт мог бы съехать, и видно, что он не съезжает. Довод сильнее
// просеивания по длинам — это не оценка, а сверка текста.
const READ =
    "прочитано построчно по обеим книгам: латинская печатает больше или меньше слов, но стих " +
    "стоит под своим номером. Там, где у славянской есть лишний стих, латинская держит его " +
    "внутри соседнего — счёт от этого не съезжает";

const SCREENED =
    "просеяно сравнением длин стихов: «стих под своим номером» объясняет главу лучше любого " +
    "сдвига в пределах шести стихов. Греческий короче или длиннее, но нумерация не съезжает. " +
    "Построчно НЕ вычитывалось";

